    'ctc.form.looking': 'Що вас цікавить?',
    'ctc.form.chip1': 'Off-plan запуски', 'ctc.form.chip2': 'Готова нерухомість', 'ctc.form.chip3': 'Управління портфелем', 'ctc.form.chip4': 'Інвест-консалтинг', 'ctc.form.chip5': 'Holiday-let', 'ctc.form.chip6': 'Сімейний дім',
    'ctc.form.ticket': 'Орієнтовний бюджет',
    'ctc.form.t1': 'До 1М AED', 'ctc.form.t2': '1М — 3М AED', 'ctc.form.t3': '3М — 8М AED', 'ctc.form.t4': '8М — 20М AED', 'ctc.form.t5': '20М+ AED',
    'ctc.form.horizon': 'Горизонт',
    'ctc.form.h1': 'До 2 років', 'ctc.form.h2': '2 — 5 років', 'ctc.form.h3': '5+ років', 'ctc.form.h4': 'Відкритий / стратегічний',
    'ctc.form.notes': 'Щось ще?',
    'ctc.form.notes_ph': 'Бекграунд, поточний портфель, конкретні проєкти, які розглядаєте…',
    'ctc.form.submit': 'Надіслати',
    'ctc.form.privacy': 'Ваша інформація конфіденційна і не передається третім особам.',
    'ctc.success.title': 'Дякую',
    'ctc.success.body': 'Запит отримано. Зв\'яжуся з вами протягом 24 годин.',
    'ctc.success.urgent': 'Якщо терміново — найшвидше у WhatsApp:',
    'ctc.loc.eyebrow': 'Базуюся в',
    'ctc.loc.head': 'Дубаї, <em>ОАЕ.</em>',
    'ctc.loc.body1': 'Зустрічі особисто — у вас удома, у шоурумі забудовника або за тихим столом десь на Sheikh Zayed Road. Або віддалено, однією з п\'яти мов.',
    'ctc.loc.body2': 'Години роботи: неділя — четвер, 9:00 — 19:00 GMT+4. Поза годинами — за домовленістю.',
    'foot.tagline': 'Менеджер портфеля нерухомості та інвестиційний консультант. У Дубаї.',
    'foot.tagline_long': 'Менеджер портфеля нерухомості та інвестиційний консультант. У Дубаї. Працюю з приватними клієнтами по ОАЕ, Європі та СНД.',
    'foot.navigate': 'Навігація', 'foot.direct': 'Зв\'язатися', 'foot.languages': 'Мови', 'foot.location': 'Дубай, ОАЕ', 'foot.copyright': '© 2026 Назар Кошляк',

    'wd.nav.hero': 'Вступ', 'wd.nav.safer': 'Безпечніше', 'wd.nav.yours': 'Ваше', 'wd.nav.live': 'Жити', 'wd.nav.tomorrow': 'Завтра', 'wd.nav.talk': 'Поговоримо',
    'wd.hero.eyebrow': 'Короткий гід для серйозних інвесторів',
    'wd.hero.head': 'Чому <em>Дубай</em>?',
    'wd.thesis.eyebrow': 'Теза',
    'wd.thesis.head': 'У Дубаї ваші гроші та ваша родина <em>у більшій безпеці</em>, ніж майже будь-де на Землі.',
    'wd.thesis.sub': 'Без податків. Світовий рівень безпеки. Росте швидше за будь-яке велике місто світу.',
    'wd.divider.safer.tag': 'Розділ 1 · Безпечніше', 'wd.divider.safer': 'Безпечніше.',
