    'wd.nav.hero': 'Einleitung', 'wd.nav.safer': 'Sicherer', 'wd.nav.yours': 'Ihr', 'wd.nav.live': 'Leben', 'wd.nav.tomorrow': 'Morgen', 'wd.nav.talk': 'Sprechen',
    'wd.hero.eyebrow': 'Ein kurzer Leitfaden für ernsthafte Investoren',
    'wd.hero.head': 'Warum <em>Dubai</em>?',
    'wd.thesis.eyebrow': 'Die These',
    'wd.thesis.head': 'In Dubai sind Ihr Geld und Ihre Familie <em>sicherer</em> als fast überall sonst auf der Welt.',
    'wd.thesis.sub': 'Steuerfrei. Weltweit höchste Sicherheit. Wächst schneller als jede Großstadt der Welt.',
    'wd.divider.safer.tag': 'Kapitel 1 · Sicherer', 'wd.divider.safer': 'Sicherer.',
    'wd.divider.yours.tag': 'Kapitel 2 · Ihr', 'wd.divider.yours': 'Ihr.',
    'wd.divider.live.tag': 'Kapitel 3 · Leben', 'wd.divider.live': 'Leben.',
    'wd.divider.tomorrow.tag': 'Kapitel 4 · Morgen', 'wd.divider.tomorrow': 'Morgen.',
    'wd.safety.tag': 'Sicherheit',
    'wd.safety.head': 'Das <em>sicherste Land</em> der Welt.',
    'wd.safety.sub': 'Die VAE sind 2026 weltweit auf Platz 1 für Sicherheit — vor Katar, Andorra und der Schweiz. Numbeo Safety Index 2026 — VAE 86,0. Dubai-Kriminalitätsindex bei 15/100 — die niedrigste „sehr niedrige" Stufe.',
    'wd.safety.b1': '200+ Nationalitäten leben friedlich nebeneinander.',
    'wd.safety.b2': 'Eigentumsrechte geschützt durch das Dubai Land Department — jeder Titel registriert.',
    'wd.safety.b3': 'Dieselbe politische Führung seit Jahrzehnten — langfristige Stabilität, vorhersehbare Regeln.',
    'wd.safety.src': 'Quelle: Numbeo Safety Index 2026.',
    'wd.tax.tag': 'Steuern',
    'wd.tax.head': '<em>0%</em> Einkommen. <em>0%</em> Kapitalertrag. <em>0%</em> Grundsteuer.',
    'wd.tax.sub': 'Behalten Sie, was Sie verdienen. Für immer. 100% der Mieteinnahmen gehören Ihnen. Keine jährliche Grundsteuer. Keine Steuer beim Verkauf. Keine Erbschaftsteuer.',
    'wd.tax.s1': 'Einkommensteuer', 'wd.tax.s2': 'Kapitalertrag', 'wd.tax.s3': 'Grundsteuer',
    'wd.tax.src': 'Quelle: PwC Worldwide Tax Summaries 2026.',
    'wd.price.tag': 'Preis',
    'wd.price.head': 'Der <em>halbe</em> Preis von London. Ein <em>Zehntel</em> von Monaco.',
    'wd.price.sub': 'Eine zentrale Wohnung in Dubai kostet pro Quadratmeter weniger als in jeder anderen Top-Metropole der Welt. USD/m² · zentral wohnen · 2025.',
    'wd.price.src': 'Quellen: Global Property Guide · Monaco IMSEE 2025 · Savills Singapore · DXB Off Plan 2025.',
    'wd.yield.tag': 'Cashflow',
    'wd.yield.head': '<em>Doppelter</em> Cashflow gegenüber jeder Welthauptstadt.',
    'wd.yield.sub': 'Dubai-Wohnungen liefern 6–8% Bruttorendite. Steuerfrei — also netto ≈ brutto. In London, Paris und Singapur verlieren Sie 30–45% der Miete an Steuern.',
    'wd.yield.src': 'Quellen: The Key Advisory 2026 · Global Property Guide · Sands of Wealth.',
    'wd.growth.tag': 'Kapitalwachstum',
    'wd.growth.head': '<em>+122%</em> in fünf Jahren.',
    'wd.growth.sub': 'Die Preise für zentrale Dubai-Wohnungen haben sich seit 2020 mehr als verdoppelt. USD/m² · indexiert · zentral wohnen.',
    'wd.growth.b1': '<strong>2022:</strong> +30,86% im Jahresvergleich.',
    'wd.growth.b2': '<strong>2025:</strong> +11,6% im Jahresvergleich (aktuell).',
    'wd.growth.b3': '<strong>H1 2025:</strong> AED 262,7 Mrd. bei 94.000+ Transaktionen.',
    'wd.growth.b4': '<strong>Ausländische Käufer:</strong> 68% der Transaktionen, Ende 2024.',
    'wd.growth.b5': '<strong>Treiber:</strong> Vision 2030 · D33-Plan.',
    'wd.growth.src': 'Quellen: Place Overseas · DXB Off Plan · Dubai Land Department.',
    'wd.own.tag': 'Eigentum',
    'wd.own.head': '<em>40%</em> des Wohnwerts in ausländischem Besitz.',
    'wd.own.sub': 'Der größte Teil Dubais steht Ausländern offen — und die meisten Käufer sind es bereits. 100% Eigentum auf Ihren Namen (oder Firma). Kein lokaler Partner. Keine Residenz erforderlich. Jeder Titel wird beim Dubai Land Department registriert.',
    'wd.own.src': 'Quellen: International Tax Observatory 2024 · Dubai Land Department · ValuStrat 2025.',
    'wd.alt.tag': 'Alternativen',
    'wd.alt.head': '<em>Es ist nicht einmal vergleichbar.</em>',
    'wd.alt.sub': 'Dubai ist der einzige große Immobilienmarkt ohne Eigentumsbeschränkungen, ohne Steuern und mit einem 10-Jahres-Visum. Bali-Renditen erscheinen am höchsten, bis man das Kleingedruckte liest: kein Freehold, Treuhandstrukturen, Währungsrisiko. Thailand begrenzt ausländisches Eigentum auf 49%. Georgien ist offen, aber der Markt ist 100× kleiner als Dubai.',
    'wd.alt.src': 'Quellen: Housebook MENA 2025 · ValuStrat · Tekce 2026.',
    'wd.protect.tag': 'Käuferschutz',
    'wd.protect.head': 'Ihr Geld liegt im <em>Treuhandkonto</em>. Nicht in der Tasche des Entwicklers.',
    'wd.protect.sub': 'Jeder Off-Plan-Kauf ist durch das Dubai Land Department Gesetz geschützt. Dies ist der strengste Off-Plan-Käuferschutzrahmen im GCC — und stärker als die meisten europäischen Märkte.',
    'wd.protect.src': 'Quellen: RERA · Dubai Land Department · Engel & Völkers Escrow Guide 2026.',
